{"command": "cd /app && python3 - << 'PYEOF'
import json, glob
import numpy as np

lib = {}
for f in glob.glob('data/*.jsonl') + glob.glob('data/*.json'):
    for line in open(f):
        line=line.strip()
        if not line: continue
        d=json.loads(line)
        m = d.get('m') or d.get('tail_mean')
        if m and len(m)==60:
            key = d.get('exp', f)
            lib.setdefault(key, []).append((d.get('t',-1), {int(k):v for k,v in m.items()}))

chans = [0,2,10,12,16,21,25,27,35,48,49,57,44]
def show(run):
    rows = sorted(lib[run])
    print(f"--- {run} ---")
    hdr = "t    " + "".join(f"ch{c:<7}" for c in chans)
    print(hdr)
    for t, m in rows:
        print(f"{t:<5}" + "".join(f"{m[c]:<9.3f}" for c in chans))

for run in ['fr','rel_shortpin','rel_negpin','rel_longpin']:
    show(run)
print("\npins:")
for run in lib:
    if run.startswith('pin') or run.startswith('d_'):
        for t,m in sorted(lib[run]):
            print(f"{run:22s} t={t:<4} " + "".join(f"{m[c]:<9.3f}" for c in chans))
